//! TRUSTED DIAGNOSTIC ONLY. This is a native Rust-layout snapshot, not an artifact
//! format suitable for production or untrusted inputs. It is tied to this exact
//! host binary, Rust ABI, target, and fixture set. Pointer sites are inferred;
//! a portable typed archive and verifier would be required to ship this idea.
use baml_exec::PackEnvelope;
use std::{
    alloc::{GlobalAlloc, Layout, System},
    cell::{Cell, RefCell},
    collections::BTreeMap,
    ptr,
    sync::atomic::{AtomicUsize, Ordering},
};

const MAGIC: &[u8; 8] = b"DIAGIMG1";
const CAPACITY: usize = 64 * 1024 * 1024;
static BASE: AtomicUsize = AtomicUsize::new(0);
static END: AtomicUsize = AtomicUsize::new(0);
thread_local! {
    static CAPTURING: Cell<bool> = const { Cell::new(false) };
    static NEXT: Cell<usize> = const { Cell::new(0) };
    static ALLOCS: Cell<usize> = const { Cell::new(0) };
    static REQUESTED: Cell<usize> = const { Cell::new(0) };
    static TRACKING: Cell<bool> = const { Cell::new(false) };
    static BLOCKS: RefCell<BTreeMap<usize, usize>> = const { RefCell::new(BTreeMap::new()) };
}
pub struct Allocator;
#[global_allocator]
static ALLOCATOR: Allocator = Allocator;

fn in_arena(p: *mut u8) -> bool {
    let n = p as usize;
    n >= BASE.load(Ordering::Relaxed) && n < END.load(Ordering::Relaxed)
}
unsafe impl GlobalAlloc for Allocator {
    unsafe fn alloc(&self, layout: Layout) -> *mut u8 {
        if CAPTURING.try_with(Cell::get).unwrap_or(false) {
            let base = BASE.load(Ordering::Relaxed);
            let start =
                NEXT.with(|n| (base + n.get() + layout.align() - 1) & !(layout.align() - 1));
            let end = start.checked_add(layout.size()).unwrap();
            if end > END.load(Ordering::Relaxed) {
                std::process::abort();
            }
            NEXT.with(|n| n.set(end - base + 16));
            if TRACKING.with(Cell::get) {
                if layout.align() > 16 {
                    std::process::abort();
                }
                CAPTURING.with(|c| c.set(false));
                BLOCKS.with(|b| {
                    b.borrow_mut().insert(start, layout.size());
                });
                CAPTURING.with(|c| c.set(true));
            }
            ALLOCS.with(|n| n.set(n.get() + 1));
            REQUESTED.with(|n| n.set(n.get() + layout.size()));
            unsafe {
                ptr::write_bytes(start as *mut u8, 0, layout.size());
            }
            start as *mut u8
        } else {
            unsafe { System.alloc(layout) }
        }
    }
    unsafe fn alloc_zeroed(&self, layout: Layout) -> *mut u8 {
        if CAPTURING.try_with(Cell::get).unwrap_or(false) {
            unsafe { self.alloc(layout) }
        } else {
            unsafe { System.alloc_zeroed(layout) }
        }
    }
    unsafe fn dealloc(&self, p: *mut u8, layout: Layout) {
        if !in_arena(p) {
            unsafe {
                System.dealloc(p, layout);
            }
        } else if CAPTURING.try_with(Cell::get).unwrap_or(false) && TRACKING.with(Cell::get) {
            CAPTURING.with(|c| c.set(false));
            BLOCKS.with(|b| {
                b.borrow_mut().remove(&(p as usize));
            });
            CAPTURING.with(|c| c.set(true));
        }
    }
    unsafe fn realloc(&self, p: *mut u8, layout: Layout, new_size: usize) -> *mut u8 {
        if in_arena(p) {
            let result =
                unsafe { self.alloc(Layout::from_size_align(new_size, layout.align()).unwrap()) };
            if !result.is_null() {
                unsafe {
                    ptr::copy_nonoverlapping(p, result, layout.size().min(new_size));
                    self.dealloc(p, layout);
                }
            }
            result
        } else {
            unsafe { System.realloc(p, layout, new_size) }
        }
    }
}

pub struct Arena {
    base: *mut u8,
    layout: Layout,
}
impl Arena {
    fn new(size: usize) -> Self {
        assert_eq!(
            BASE.load(Ordering::Relaxed),
            0,
            "only one image per diagnostic process"
        );
        let layout = Layout::from_size_align(size.max(1), 4096).unwrap();
        let base = unsafe { System.alloc(layout) };
        if base.is_null() {
            std::alloc::handle_alloc_error(layout);
        }
        BASE.store(base as usize, Ordering::Relaxed);
        END.store(base as usize + size, Ordering::Relaxed);
        Self { base, layout }
    }
}
impl Drop for Arena {
    fn drop(&mut self) {
        CAPTURING.with(|c| c.set(false));
        // The host has finished shutdown and dropped the complete engine before
        // releasing this backing allocation. No process-lifetime engine leak.
        unsafe {
            System.dealloc(self.base, self.layout);
        }
        END.store(0, Ordering::Relaxed);
        BASE.store(0, Ordering::Relaxed);
    }
}

fn capture(payload: &[u8], tracking: bool) -> (Arena, *mut PackEnvelope, usize, usize) {
    let arena = Arena::new(CAPACITY);
    TRACKING.with(|t| t.set(tracking));
    CAPTURING.with(|c| c.set(true));
    let envelope: PackEnvelope =
        borsh::from_slice(payload).expect("trusted compiler-produced fixture");
    let root = Box::into_raw(Box::new(envelope));
    CAPTURING.with(|c| c.set(false));
    let used = NEXT.with(Cell::get);
    let count = ALLOCS.with(Cell::get);
    (arena, root, used, count)
}

fn u64_at(bytes: &[u8], offset: usize) -> usize {
    u64::from_le_bytes(bytes[offset..offset + 8].try_into().unwrap()) as usize
}
fn number(out: &mut Vec<u8>, n: usize) {
    out.extend_from_slice(&(n as u64).to_le_bytes());
}

fn snapshot(payload: &[u8]) -> Vec<u8> {
    let (arena, root, used, count) = capture(payload, true);
    // Compact only live allocations. Temporary strings, old Vec growth
    // buffers and decode proxies must not inflate the loaded image.
    let blocks = BLOCKS.with(|b| b.borrow().iter().map(|(&p, &n)| (p, n)).collect::<Vec<_>>());
    let mut layout = Vec::new();
    let mut size = 0;
    for (address, bytes) in blocks {
        size = (size + 15) & !15;
        layout.push((address, bytes, size));
        size += bytes;
    }
    let mut data = vec![0u8; (size + 7) & !7];
    let mut root_offset = None;
    let mut relocations = Vec::new();
    for &(address, bytes, target) in &layout {
        unsafe {
            ptr::copy_nonoverlapping(address as *const u8, data.as_mut_ptr().add(target), bytes);
        }
        if address == root as usize {
            root_offset = Some(target);
        }
        for offset in (0..bytes.saturating_sub(7)).step_by(8) {
            let value = u64_at(&data, target + offset);
            let slot = layout.partition_point(|&(address, _, _)| address <= value);
            if slot > 0 {
                let (start, len, placed) = layout[slot - 1];
                if value <= start + len {
                    let relative = placed + value - start;
                    data[target + offset..target + offset + 8]
                        .copy_from_slice(&(relative as u64).to_le_bytes());
                    relocations.push(target + offset);
                }
            }
        }
    }
    // No host-address inference: small integers/instruction bytes can overlap
    // a code address. These fixtures require all reachable heap data to be in
    // the image; complete Borsh round-trip checks gate every tested image.
    let mut result = Vec::new();
    number(&mut result, data.len());
    number(&mut result, root_offset.unwrap());
    number(&mut result, count);
    number(&mut result, relocations.len());
    for offset in relocations {
        number(&mut result, offset << 1);
    }
    result.extend_from_slice(&data);
    eprintln!(
        "IMAGE_CAPTURE:{{\"arena_bytes\":{used},\"allocations\":{count},\"requested_bytes\":{},\"live_bytes\":{},\"snapshot_bytes\":{}}}",
        REQUESTED.with(Cell::get),
        data.len(),
        result.len()
    );
    // We captured only a deserialized template, before OS resources, native
    // pointers, telemetry workers or engine state exist. Destroy the template
    // normally, then release its arena.
    unsafe {
        ptr::drop_in_place(root);
    }
    drop(arena);
    result
}

fn load_snapshot(data: &[u8]) -> (PackEnvelope, Arena) {
    let used = u64_at(data, 0);
    let root = u64_at(data, 8);
    let count = u64_at(data, 24);
    let table_end = 32 + count.checked_mul(8).unwrap();
    assert_eq!(data.len() - table_end, (used + 7) & !7);
    assert!(root + size_of::<PackEnvelope>() <= used && root % align_of::<PackEnvelope>() == 0);
    let arena = Arena::new(used);
    unsafe {
        ptr::copy_nonoverlapping(data[table_end..].as_ptr(), arena.base, used);
    }
    for index in 0..count {
        let site = u64_at(data, 32 + index * 8);
        let offset = site >> 1;
        assert!(offset % 8 == 0 && offset + 8 <= used);
        let address = unsafe { arena.base.add(offset).cast::<usize>() };
        let relative = unsafe { address.read() };
        assert_eq!(site & 1, 0);
        assert!(relative <= used);
        let origin = arena.base as usize;
        unsafe {
            address.write(origin + relative);
        }
    }
    let envelope = unsafe { ptr::read(arena.base.add(root).cast::<PackEnvelope>()) };
    (envelope, arena)
}

pub fn decode(section: &[u8]) -> Result<(PackEnvelope, Option<Arena>), String> {
    let payload =
        baml_artifact::decode_payload(baml_artifact::ArtifactKind::PackedProgram, section)
            .map_err(|e| e.to_string())?;
    // Ordinary prepared Borsh fixture is the matched control in the same binary.
    if payload.get(4..12) != Some(MAGIC.as_slice()) {
        return borsh::from_slice(payload)
            .map(|e| (e, None))
            .map_err(|e| e.to_string());
    }
    assert_eq!(
        u32::from_le_bytes(payload[..4].try_into().unwrap()) as usize,
        payload.len() - 4
    );
    let mode = u64_at(payload, 12);
    let bytes = &payload[20..];
    let decompressed;
    let data = if mode >= 3 {
        decompressed = lz4_flex::decompress_size_prepended(bytes).map_err(|e| e.to_string())?;
        decompressed.as_slice()
    } else {
        bytes
    };
    match mode {
        1 => {
            let (arena, root, _, _) = capture(data, false);
            Ok((unsafe { root.read() }, Some(arena)))
        }
        2 | 4 => {
            let (envelope, arena) = load_snapshot(data);
            Ok((envelope, Some(arena)))
        }
        3 => borsh::from_slice(data)
            .map(|e| (e, None))
            .map_err(|e| e.to_string()),
        _ => Err("unknown diagnostic mode".into()),
    }
}

// Separate explicit diagnostic flag, never available in shipping baml binaries.
pub fn tooling() -> bool {
    let args: Vec<_> = std::env::args_os().collect();
    let Some(verb) = args.get(1).and_then(|s| s.to_str()) else {
        return false;
    };
    if verb == "--diagnostic-repack" {
        assert_eq!(args.len(), 6);
        let source = std::fs::read(&args[2]).unwrap();
        let section = macho_section(&source);
        let payload =
            baml_artifact::decode_payload(baml_artifact::ArtifactKind::PackedProgram, section)
                .unwrap();
        let mode: usize = args[4].to_str().unwrap().parse().unwrap();
        let data = match mode {
            1 => payload.to_vec(),
            2 | 4 => snapshot(payload),
            3 => payload.to_vec(),
            _ => panic!("bad mode"),
        };
        let bytes = if mode >= 3 {
            lz4_flex::compress_prepend_size(&data)
        } else {
            data
        };
        let mut protocol = MAGIC.to_vec();
        number(&mut protocol, mode);
        protocol.extend_from_slice(&bytes);
        let encoded =
            baml_artifact::encode(baml_artifact::ArtifactKind::PackedProgram, &protocol).unwrap();
        let host = std::fs::read(&args[3]).unwrap();
        let mut output = std::fs::File::create(&args[5]).unwrap();
        libsui::Macho::from(host)
            .unwrap()
            .write_section(baml_exec::PACK_SECTION_NAME, encoded)
            .unwrap()
            .build_and_sign(&mut output)
            .unwrap();
        use std::os::unix::fs::PermissionsExt;
        output
            .set_permissions(std::fs::Permissions::from_mode(0o755))
            .unwrap();
        return true;
    }
    if verb == "--diagnostic-verify" {
        assert_eq!(args.len(), 4);
        let original = std::fs::read(&args[2]).unwrap();
        let image = std::fs::read(&args[3]).unwrap();
        let original_payload = baml_artifact::decode_payload(
            baml_artifact::ArtifactKind::PackedProgram,
            macho_section(&original),
        )
        .unwrap();
        let (envelope, arena) = decode(macho_section(&image)).unwrap();
        let restored = borsh::to_vec(&envelope).unwrap();
        assert!(
            restored == original_payload,
            "graph differs: lengths {} / {}, first mismatch {:?}",
            restored.len(),
            original_payload.len(),
            restored
                .iter()
                .zip(original_payload)
                .position(|(a, b)| a != b)
        );
        drop(envelope);
        drop(arena);
        println!("full graph round-trip verified");
        return true;
    }
    false
}
fn macho_section(b: &[u8]) -> &[u8] {
    let mut p = 32;
    for _ in 0..u32::from_le_bytes(b[16..20].try_into().unwrap()) {
        let kind = u32::from_le_bytes(b[p..p + 4].try_into().unwrap());
        let size = u32::from_le_bytes(b[p + 4..p + 8].try_into().unwrap()) as usize;
        if kind == 0x19 {
            let n = u32::from_le_bytes(b[p + 64..p + 68].try_into().unwrap());
            for i in 0..n as usize {
                let s = p + 72 + i * 80;
                if b[s..s + 16].split(|b| *b == 0).next().unwrap()
                    == baml_exec::PACK_SECTION_NAME.as_bytes()
                {
                    let len = u64_at(b, s + 40);
                    let offset = u32::from_le_bytes(b[s + 48..s + 52].try_into().unwrap()) as usize;
                    return &b[offset..offset + len];
                }
            }
        }
        p += size;
    }
    panic!("missing fixture section");
}

